        axis,pos=bars[0]
        color=next(v for row in grid for v in row if v not in (1,2))
        cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        if axis=='h':
            lo=min(r for r,c in cells); hi=max(r for r,c in cells)
            line=hi+1 if pos>hi else lo-1
            if 0<=line<h:
                for c in range(w): out[line][c]=8
        else:
            lo=min(c for r,c in cells); hi=max(c for r,c in cells)
            line=hi+1 if pos>hi else lo-1
            if 0<=line<w:
                for r in range(h): out[r][line]=8
    return out
'''
